class Solution:
    def hasSpecialSubstring(self, s: str, k: int) -> bool:
        n = len(s)
        i = 0

        while i < n:
            # Start of a block
            j = i
            while j < n and s[j] == s[i]:
                j += 1
            length = j - i

            if length == k:
                left_ok = (i == 0) or (s[i-1] != s[i])
                right_ok = (j == n) or (j < n and s[j] != s[i])
                if left_ok and right_ok:
                    return True

            i = j  # Move to next group

        return False
